SELECT FROM model_assets WHERE 1 = 1
AND ( LOWER(name) LIKE CONCAT('%', LOWER(#{q}), '%') OR LOWER(COALESCE(description, '')) LIKE CONCAT('%', LOWER(#{q}), '%') OR LOWER(tags_json) LIKE CONCAT('%', LOWER(#{q}), '%') )
AND category = #{category}
AND format = #{format}
AND element_type_id = #{elementTypeId}
ORDER BY download_count DESC, created_at DESC ORDER BY name ASC ORDER BY created_at DESC

mapper.update:
UPDATE model_assets
SET view_count = view_count + 1
WHERE id = #{id}

UPDATE model_assets
SET download_count = download_count + 1
WHERE id = #{id}
